using UnityEngine;

namespace TowerDefense
{
    // All the game's audio clips, generated by LevelBuilder (Assets/Audio/Generated/) and assigned here,
    // so no gameplay script ever references a clip: they ask AudioManager for an SfxId or a MusicId.
    [CreateAssetMenu(menuName = "Tower Defense/Audio Library", fileName = "AudioLibrary")]
    public class AudioLibrary : ScriptableObject
    {
        [Tooltip("Indexed by SfxId.")]
        public AudioClip[] sfx = new AudioClip[(int)SfxId.Count];
        [Tooltip("Indexed by SfxId: each effect's base volume, 0..1.")]
        public float[] sfxVolume = new float[(int)SfxId.Count];
        public AudioClip menuMusic;
        public AudioClip gameMusic;
        public AudioClip bossMusic;
        public AudioClip winJingle;
        public AudioClip loseJingle;

        public AudioClip Sfx(SfxId id)
        {
            int i = (int)id;
            return sfx != null && i >= 0 && i < sfx.Length ? sfx[i] : null;
        }

        public float SfxVolume(SfxId id)
        {
            int i = (int)id;
            return sfxVolume != null && i >= 0 && i < sfxVolume.Length ? sfxVolume[i] : 1f;
        }

        public AudioClip Music(MusicId id)
        {
            switch (id)
            {
                case MusicId.Menu: return menuMusic;
                case MusicId.Game: return gameMusic;
                case MusicId.Boss: return bossMusic;
                default: return null;
            }
        }

        public AudioClip Jingle(JingleId id)
        {
            return id == JingleId.Win ? winJingle : loseJingle;
        }
    }
}
